package com.finstack.budget;
import com.finstack.alert.*; import com.finstack.transaction.TransactionRepository; import com.finstack.user.User; import org.springframework.stereotype.Service;
import java.math.*; import java.time.*;
@Service public class BudgetEvaluationService {
 private final BudgetRepository budgets; private final TransactionRepository transactions; private final AlertRepository alerts;
 public BudgetEvaluationService(BudgetRepository b,TransactionRepository t,AlertRepository a){budgets=b;transactions=t;alerts=a;}
 public void evaluate(User user,OffsetDateTime time){LocalDate month=time.withOffsetSameInstant(ZoneOffset.UTC).toLocalDate().withDayOfMonth(1);OffsetDateTime start=month.atStartOfDay().atOffset(ZoneOffset.UTC),end=month.plusMonths(1).atStartOfDay().atOffset(ZoneOffset.UTC);for(Budget b:budgets.findAllByUserIdAndBudgetMonthAndActive(user.getId(),month,true)){BigDecimal spent=transactions.totalCompletedExpenseForMonth(user.getId(),start,end);evaluateBudget(user,b,spent);b.getCategories().forEach(allocation->evaluateCategory(user,b,allocation.getCategory(),allocation.getCategoryLimit(),zero(transactions.categoryCompletedExpenseForMonth(user.getId(),allocation.getCategory().getId(),start,end))));}}
 private void evaluateBudget(User u,Budget b,BigDecimal spent){BigDecimal usage=percent(spent,b.getTotalLimit());if(usage.compareTo(BigDecimal.valueOf(b.getWarningThresholdPercent()))>=0&&!alerts.existsByRelatedBudgetIdAndAlertType(b.getId(),AlertType.BUDGET_WARNING))alerts.save(new Alert(u,AlertType.BUDGET_WARNING,AlertSeverity.WARNING,"Budget warning","Budget '"+b.getName()+"' reached its warning threshold",b));if(usage.compareTo(BigDecimal.valueOf(100))>0&&!alerts.existsByRelatedBudgetIdAndAlertType(b.getId(),AlertType.BUDGET_EXCEEDED))alerts.save(new Alert(u,AlertType.BUDGET_EXCEEDED,AlertSeverity.HIGH,"Budget exceeded","Budget '"+b.getName()+"' exceeded its monthly limit",b));}
 private void evaluateCategory(User u,Budget b,com.finstack.category.TransactionCategory c,BigDecimal limit,BigDecimal spent){BigDecimal usage=percent(spent,limit);if(usage.compareTo(BigDecimal.valueOf(b.getWarningThresholdPercent()))>=0&&!alerts.existsByRelatedBudgetIdAndRelatedCategoryIdAndAlertType(b.getId(),c.getId(),AlertType.CATEGORY_BUDGET_WARNING))alerts.save(new Alert(u,AlertType.CATEGORY_BUDGET_WARNING,AlertSeverity.WARNING,"Category budget warning","Category '"+c.getName()+"' reached its warning threshold",b,c));if(usage.compareTo(BigDecimal.valueOf(100))>0&&!alerts.existsByRelatedBudgetIdAndRelatedCategoryIdAndAlertType(b.getId(),c.getId(),AlertType.CATEGORY_BUDGET_EXCEEDED))alerts.save(new Alert(u,AlertType.CATEGORY_BUDGET_EXCEEDED,AlertSeverity.HIGH,"Category budget exceeded","Category '"+c.getName()+"' exceeded its allocation",b,c));}
 private BigDecimal percent(BigDecimal value,BigDecimal limit){return value.multiply(BigDecimal.valueOf(100)).divide(limit,2,RoundingMode.HALF_UP);} private BigDecimal zero(BigDecimal n){return n==null?BigDecimal.ZERO:n;}
}
